#   python itemfactory/tools/pitfalls.py            → seeds/*.json 의 각 틀에 "pitfalls" 를 써 넣는다 (있으면 덮어씀)
#
# 감점 요인의 뜻 (Park, 2026-09-08): 채점 규칙이 아니라 **그 문항에서 조심해야 할 실수거리**.
#   · 빠지면 논리적 연결이 끊겨서 반드시 적어야 하는 진술 (근거 누락)
#   · 얼핏 당연해 보여서 선후 관계를 바꿔 적기 쉬운 것 (결과를 근거처럼 씀, 방향 뒤집힘)
#   · 바꿔 쓰기 쉬운 두 값 (거리↔중점, 반지름↔지름, 내각↔외각 …)
# 경기도교육청 채점기준표의 1점(부분) 수준 문구·'미인정 기준'과 같은 결의 것들이다 (itemfactory/reference/gyeonggi/).
#
# 항목: {"text": 실수 내용, "on": 해당 채점 요소 이름의 일부, "effect": "부분" | "불인정"}
#   부분   = 그 요소를 부분 수준(1점 등)으로 매긴다     불인정 = 그 요소를 0으로 매긴다
