        {"text": "올라간 거리와 내려온 거리를 같은 x로 둠 (길이 다르다는 조건 무시)", "on": "조건", "effect": "불인정"},
        {"text": "시간 조건을 거리로, 거리 조건을 시간으로 바꿔 씀", "on": "연립", "effect": "불인정"},
        {"text": "분모를 없앨 때 우변의 시간에는 곱하지 않음", "on": "풀이", "effect": "부분"},
        {"text": "구한 x, y 중 묻지 않은 쪽을 답으로 씀 (구하는 대상 혼동)", "on": "풀이", "effect": "부분"},
